<script setup lang="ts">import {onMounted,ref} from 'vue';import {supabase} from '@/lib/supabase'
const rows=ref<any[]>([]),busy=ref(false),error=ref(''),selected=ref<any>(null),amount=ref(0),method=ref('cash'),note=ref('')
async function load(){const {data,error:e}=await supabase.from('credits').select('*,customers(name,phone),sales(receipt_no)').order('created_at',{ascending:false});if(e)error.value=e.message;else rows.value=data??[]}
async function pay(){if(!selected.value)return;busy.value=true;error.value='';try{const {error:e}=await supabase.rpc('record_credit_payment',{p_credit_id:selected.value.id,p_amount:Number(amount.value),p_method:method.value,p_note:note.value||null});if(e)throw e;selected.value=null;amount.value=0;note.value='';await load()}catch(e:any){error.value=e.message}finally{busy.value=false}}onMounted(load)
</script><template><section class="page-wrap"><div class="page-heading"><div><h1>Customer credits</h1><p>Track amounts customers owe and record repayments.</p></div><button class="btn" @click="load">Refresh</button></div><p v-if="error" class="alert">{{error}}</p><div class="table-scroll"><table><thead><tr><th>Customer</th><th>Receipt</th><th>Amount</th><th>Balance</th><th>Status</th><th>Action</th></tr></thead><tbody><tr v-for="r in rows" :key="r.id"><td>{{r.customers?.name??'—'}}</td><td>{{r.sales?.receipt_no??r.sale_id}}</td><td>UGX {{Number(r.amount).toLocaleString()}}</td><td>UGX {{Number(r.balance).toLocaleString()}}</td><td>{{r.status}}</td><td><button v-if="r.status==='open'" class="link" @click="selected=r;amount=Number(r.balance)">Record payment</button></td></tr><tr v-if="!rows.length"><td colspan="6" class="empty">No credit records.</td></tr></tbody></table></div><div v-if="selected" class="modal-backdrop" @click.self="selected=null"><form class="modal" @submit.prevent="pay"><h2>Record customer payment</h2><p>{{selected.customers?.name}} · Balance UGX {{Number(selected.balance).toLocaleString()}}</p><label>Amount<input v-model.number="amount" type="number" min="0.01" :max="selected.balance" step="0.01" class="control" required></label><label>Method<select v-model="method" class="control"><option value="cash">Cash</option><option value="bank">Bank</option><option value="mobile_money">Mobile money</option></select></label><label>Note<input v-model="note" class="control"></label><div class="modal-actions"><button type="button" class="btn" @click="selected=null">Cancel</button><button class="btn primary" :disabled="busy||amount<=0||amount>selected.balance">{{busy?'Saving…':'Save payment'}}</button></div></form></div></section></template>
